'@

function Get-CertificateRecords {
    Import-EmbeddedEngine
    return [LuZu.TampObeliskZipperV16.CertificateCatalog]::All($EmbeddedCertificateHex)
}
function Show-CertificateInventory {
    Import-EmbeddedEngine
    [LuZu.TampObeliskZipperV16.CertificateCatalog]::Inventory($EmbeddedCertificateHex) | Write-Output
    if ($VeryVerbose) {
        foreach ($entry in [LuZu.TampObeliskZipperV16.CertificateCatalog]::All($EmbeddedCertificateHex)) {
            Write-Output ('CERT {0} [{1}] {2} SHA256={3}' -f $entry.Id,$entry.Group,$entry.Subject,$entry.Sha256)
        }
    }
    Write-Output 'Public data embedded does NOT imply trusted issuer, signature path, revocation status or TAMP authorization.'
}
function Export-EmbeddedCertificate {
    if ([string]::IsNullOrWhiteSpace($CertificateId)) { throw 'Provide -CertificateId, obtained using -Mode CertificateInventory or the CSV inventory.' }
    $outdir = Assert-LocalDirectory $OutputDirectory
    Import-EmbeddedEngine
    [byte[]]$bytes=[LuZu.TampObeliskZipperV16.CertificateCatalog]::GetById($EmbeddedCertificateHex,$CertificateId)
    $fingerprint=[LuZu.TampObeliskZipperV16.Inspector]::FileHash($bytes)
    $outpath=Join-Path $outdir ('UNTRUSTED-'+$fingerprint+'.cer')
    Write-NewLocalFile -Path $outpath -Bytes $bytes
    Write-Output "Exported DER certificate: $outpath"
    Write-Output "SHA256: $fingerprint; no certificate-store writes."
}
function Export-AllEmbeddedCertificates {
    $outdir = Assert-LocalDirectory $OutputDirectory
    $records=@(Get-CertificateRecords)
    $count=0
    foreach($r in $records) {
        $file=Join-Path $outdir ('UNTRUSTED-'+$r.Sha256+'.cer')
        Write-NewLocalFile -Path $file -Bytes $r.Der
        $count++
    }
    Write-Output "Exported $count public DER certificates to $outdir. No trust-store changes."
}

try {
    switch ($Mode) {
        'CertificateInventory' { Show-CertificateInventory }
        'VerifyCertificates' { Show-CertificateInventory }
        'ExportCertificate' { Export-EmbeddedCertificate }
        'ExportAllCertificates' { Export-AllEmbeddedCertificates }
        'Obelisk' { Invoke-ObeliskAcquisition }
        'AcquireOnline' { Invoke-ObeliskAcquisition }
        'AutoUpdate' { Invoke-DailyUpdate }
        'EnableAutoUpdate' { Enable-DailyTask }
        'DisableAutoUpdate' { Disable-DailyTask }
        'AutoUpdateStatus' { Show-DailyTask }
        'SelfTest' {
            Import-EmbeddedEngine
            [LuZu.TampObeliskZipperV16.Inspector]::SelfTest() | ForEach-Object { Write-Output $_ }
            $test = [LuZu.TampObeliskZipperV16.Inspector]::TestExample()
            if (-not ($test -match 'CMS signature: VALID')) { throw 'Synthetic signed StatusQuery test failed.' }
            Write-Output 'PASS synthetic RFC 5934 StatusQuery generated, inspected and signature-verified (memory only)'
            [LuZu.TampObeliskZipperV16.CertificateCatalog]::Inventory($EmbeddedCertificateHex) | ForEach-Object { Write-Output $_ } 
        }
        'Inspect' {
            $msg = Assert-LocalFile $MessagePath
            Import-EmbeddedEngine
            $payload = [LuZu.TampObeliskZipperV16.Inspector]::ReadLocalFile($msg)
            [LuZu.TampObeliskZipperV16.Inspector]::Inspect($payload,$null,$null,$false) |
                ForEach-Object { Write-Output $_ }
        }
        'Discover' {
            $items = @(Find-LocalIr4 -GroupName $Group -ExtraDirectory $SearchDirectory)
            if ($items.Count -eq 0) {
                Write-Output "No $Group.ir4 found in local searched directories."
                Write-Output 'No official message can be created by this tool without a DoD-authorized signer.'
                Write-Output 'Use offline media to put the authentic file on disk, then run Acquire -SourcePath.'
            } else {
                $items | ForEach-Object {
                    $f = Get-Item -LiteralPath $_
                    [pscustomobject]@{ Path=$f.FullName; Bytes=$f.Length;
                        SHA256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash;
                        CMSVerified=$false }
                }
            }
        }
        'Acquire' {
            Import-EmbeddedEngine
            if ($SourcePath) {
                $src = Assert-LocalFile $SourcePath
                if ([IO.Path]::GetExtension($src) -ieq '.zip') {
                    $payload = [LuZu.TampObeliskZipperV16.Inspector]::ReadIr4Zip($src,$Group)
                } elseif ([IO.Path]::GetExtension($src) -ieq '.ir4') {
                    $name = [IO.Path]::GetFileName($src)
                    if ($name -ine "$Group.ir4" -and $name -notlike "$Group-LOCAL-UNVERIFIED-*.ir4") {
                        throw "Filename does not match requested group $Group. Use -Group matching the source file."
                    }
                    $payload = [LuZu.TampObeliskZipperV16.Inspector]::ReadLocalFile($src)
                } else { throw 'SourcePath must be an .ir4 file or .zip containing Group.ir4.' }
            } else {
                $found = @(Find-LocalIr4 -GroupName $Group -ExtraDirectory $SearchDirectory)
                if ($found.Count -eq 0) { throw "No locally available $Group.ir4. Provide -SourcePath from official offline media." }
                $hashes = @($found | ForEach-Object { (Get-FileHash -LiteralPath $_ -Algorithm SHA256).Hash } | Select-Object -Unique)
                if ($hashes.Count -ne 1) {
                    throw "Multiple distinct $Group.ir4 files found. Supply -SourcePath to select one explicitly."
                }
                $payload = [LuZu.TampObeliskZipperV16.Inspector]::ReadLocalFile($found[0])
            }
            # Structural inspection only. Independent trust establishment and
            # CMS signature verification remain explicitly separate operations.
            $report = [LuZu.TampObeliskZipperV16.Inspector]::Inspect($payload,$null,$null,$false)
            $outdir = Assert-LocalDirectory $OutputDirectory
            $hash = [LuZu.TampObeliskZipperV16.Inspector]::FileHash($payload)
            $outpath = Join-Path $outdir ("$Group-LOCAL-UNVERIFIED-$($hash.Substring(0,16)).ir4")
            Write-NewLocalFile -Path $outpath -Bytes $payload
            Write-Output "ACQUIRED LOCAL COPY (UNVERIFIED): $outpath"
            Write-Output "SHA256: $hash"
            Write-Output 'No network access; no certificate stores modified.'
            Write-Output 'WARNING: structural parse does not establish DoD origin or authorize trust changes.'
            $report | ForEach-Object { Write-Output $_ }
        }
        'GenerateTest' {
            $outdir = Assert-LocalDirectory $OutputDirectory
            Import-EmbeddedEngine
            [LuZu.TampObeliskZipperV16.Inspector]::GenerateTestFiles($outdir) |
                ForEach-Object { Write-Output $_ }
        }
        'Verify' {
            if (-not $SignerSha256) { throw 'Verify requires -SignerSha256 from an independently authenticated source.' }
            $msg = Assert-LocalFile $MessagePath
            $crt = Assert-LocalFile $SignerCertificatePath
            Import-EmbeddedEngine
            $payload = [LuZu.TampObeliskZipperV16.Inspector]::ReadLocalFile($msg)
            $certificate = [LuZu.TampObeliskZipperV16.Inspector]::ReadLocalFile($crt)
            [LuZu.TampObeliskZipperV16.Inspector]::Inspect($payload,$certificate,$SignerSha256,$true) |
                ForEach-Object { Write-Output $_ }
        }
    }
} catch {
    Write-Error -Message "TAMP Obelisk Zipper REJECTED: $($_.Exception.Message)" -ErrorAction Continue
    exit 1
}
